(() => {
  const rows = [...document.querySelectorAll('.share-dialog__ask')];
  for (const [i, row] of rows.entries()) {
    const box = row.getBoundingClientRect();
    const controls = [...row.querySelectorAll('button')].map(el => el.getBoundingClientRect());
    for (const control of controls) {
      if (control.bottom > box.bottom + 1 || control.right > box.right + 1)
        throw new Error(`request ${i}: control escapes its row`);
    }
    for (let j = 1; j < controls.length; j++) {
      if (controls[j - 1].right > controls[j].left + 1)
        throw new Error(`request ${i}: controls overlap`);
    }
    if (i && rows[i - 1].getBoundingClientRect().bottom > box.top + 1)
      throw new Error(`request ${i}: rows overlap`);
  }
  if (document.querySelector('.share-dialog').scrollWidth > document.querySelector('.share-dialog').clientWidth + 1)
    throw new Error('dialog overflows horizontally');
})()

